// Debug: mostra o que chegou
const allItems = $input.all();
const first = allItems[0]?.json || {};

// O Execute Workflow pode passar dados em diferentes estruturas
// Tenta várias possibilidades
let blueprints = [];

// Possibilidade 1: array direto
if (Array.isArray(first)) {
  blueprints = first;
}
// Possibilidade 2: campo body
else if (first.body && Array.isArray(first.body)) {
  blueprints = first.body;
}
// Possibilidade 3: item direto com keyword
else if (first.keyword) {
  blueprints = allItems.map(function(i) { return i.json; });
}
// Possibilidade 4: campo data
else if (first.data && Array.isArray(first.data)) {
  blueprints = first.data;
}

blueprints = blueprints.filter(function(b) { return b && b.keyword; });

if (blueprints.length === 0) {
  // Último recurso: usa dados de fallback para não quebrar o pipeline
  blueprints = [{
    keyword: 'fila sus',
    titulo: 'Como Consultar a Fila do SUS',
    urlSatelite: '/sus/fila-sus/',
    nicho: 'saude_publica',
    resumoBruto: 'Guia completo sobre como consultar sua posição na fila do SUS.',
    tipoAtivo: 'guia',
    volume: 12100,
    score: 7
  }];
}

return blueprints.map(function(b) {
  return { json: {
    keyword: b.keyword,
    titulo: b.titulo,
    urlSatelite: b.urlSatelite || b.urlSateliteReal,
    nicho: b.nicho,
    resumoBruto: b.resumoBruto,
    tipoAtivo: b.tipoAtivo || 'guia',
    volume: b.volume,
    score: b.score
  }};
});

const blueprints = $input.all().map(function(i) { return i.json; });

const data = new Date().toISOString().split('T')[0];

const payload = JSON.stringify({
  model: 'gpt-4o-mini',
  temperature: 0.25,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'Você é o editor sênior do Painel Saúde. Receba os blueprints do pSEO e retorne SOMENTE um objeto JSON válido. Estrutura: {"_meta": {"dataAtualizacao": "YYYY-MM-DD", "site": "meu.painelsaude.com.br", "totalBlocos": 0}, "blocos": [{"id": "slug-YYYY-MM-DD", "categoria": "saude-publica", "categoriaLabel": "Saúde Pública", "titulo": "string", "resumo": "string max 160 chars", "resumoParagrafos": ["p1","p2","p3"], "urlSateliteReal": "/slug/", "termoChave": "string", "imagemUrl": null, "quiz": {"pergunta": "string", "opcoes": ["A","B","C","D"], "respostaFiltro": {"A": "iniciante", "B": "basico", "C": "intermediario", "D": "avancado"}}, "tags": ["tag1"]}]}'
    },
    {
      role: 'user',
      content: 'Gere o feed.json para hoje (' + data + ') com base nos blueprints: ' + JSON.stringify(blueprints)
    }
  ]
});

return [{
  json: {
    blueprints: blueprints,
    quantidade: blueprints.length,
    data: data,
    site: 'meu.painelsaude.com.br',
    openai_payload: payload
  }
}];

const raw = $input.first().json;

// HTTP Request retorna a resposta da OpenAI — extrair o content
let feedData;
try {
  const content = raw.choices?.[0]?.message?.content;
  if (!content) throw new Error('Resposta da OpenAI sem content');
  feedData = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error(`JSON inválido retornado pela IA: ${e.message}`);
}

if (!feedData.blocos || !Array.isArray(feedData.blocos)) {
  throw new Error('feed.json gerado não contém array de blocos');
}

feedData.blocos = feedData.blocos.filter(b => {
  if (!b.urlSateliteReal) {
    console.warn(`Bloco '${b.id}' sem urlSateliteReal — descartado`);
    return false;
  }

  if (b.quiz && b.quiz.opcoes && b.quiz.opcoes.some(o => o.trim().length <= 1)) {
    delete b.quiz;
  }

  return true;
});

feedData._meta = {
  ...feedData._meta,
  dataAtualizacao: new Date().toISOString().split('T')[0],
  geradoEm: new Date().toISOString(),
  totalBlocos: feedData.blocos.length,
};

if (feedData.blocos.length === 0) {
  throw new Error('Todos os blocos foram descartados na validação');
}

return [{ json: { feedData, feedJson: JSON.stringify(feedData, null, 2) } }];

// Busca o feedData do nó "Validar e sanitizar JSON" (2 nós atrás)
const feedData = $('Validar e sanitizar JSON').first().json.feedData;

const urls = feedData.blocos
  .map(b => `https://meu.painelsaude.com.br${b.urlSateliteReal}`)
  .filter(Boolean);

urls.unshift('https://meu.painelsaude.com.br/feed/');

return urls.map(url => ({ json: { url } }));
